import json
import os
import subprocess
import threading
import time
from queue import Queue
from datetime import datetime, timedelta

class CommandRunner:
    def __init__(self):
        self.log_file = "run.log"
        self.command_queue = Queue()
        self.running_threads = []
        self.last_start_time = time.time()
        self.max_concurrent = 2
        self.max_per_second = 5

    def log_command(self, command, exit_status, output):
        try:
            with open(self.log_file, "a") as f:
                entry = {
                    "time": datetime.utcnow().isoformat(),
                    "command": command,
                    "exit_status": exit_status,
                    "output": output
                }
                json.dump(entry, f)
                f.write("\n")
        except Exception as e:
            raise RuntimeError(f"Failed to write log: {str(e)}")

    def worker(self):
        while True:
            try:
                command = self.command_queue.get_nowait()
                start_time = time.time()
                process = subprocess.Popen(
                    command.split(),
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    universal_newlines=True
                )
                output, _ = process.communicate()
                exit_status = process.returncode
                self.command_queue.task_done()
                self.running_threads.remove(threading.current_thread())

                if time.time() - self.last_start_time > 1:
                    self.last_start_time = time.time()
                    self.command_queue.queue.clear()

                self.log_command(command, exit_status, output)
            except Exception as e:
                if not self.command_queue.empty():
                    self.command_queue.put_nowait(command)
                raise RuntimeError(f"Command execution failed: {str(e)}")

    def start(self):
        for _ in range(self.max_concurrent):
            t = threading.Thread(target=self.worker)
            t.daemon = True
            t.start()
            self.running_threads.append(t)

    def add_command(self, command):
        if len(self.running_threads) >= self.max_concurrent:
            self.command_queue.put(command)
            return

        if time.time() - self.last_start_time > 1:
            self.last_start_time = time.time()
            self.command_queue.queue.clear()

        self.command_queue.put(command)
        self.running_threads.append(threading.current_thread())

    def process_input(self):
        try:
            while True:
                line = input().strip()
                if not line:
                    continue
                self.add_command(line)
        except EOFError:
            pass
        except Exception as e:
            print(json.dumps({"message": str(e)}), file=sys.stderr)
            exit(1)

def main():
    runner = CommandRunner()
    runner.start()
    runner.process_input()
    runner.command_queue.join()
    exit(0)

if __name__ == "__main__":
    import sys
    main()

import json
import os
import sys
import time
from datetime import datetime
from threading import Thread, Event

class CommandRunner:
    def __init__(self):
        self.command_queue = []
        self.active_threads = []
        self.throttle_event = Event()
        self.throttle_start = time.time()
        self.log_file = open('run.log', 'w', encoding='utf-8')
        self.last_command_time = 0

    def process_command(self, command):
        try:
            start_time = time.time()
            result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
            end_time = time.time()
            exit_status = result.returncode
            command_output = result.stdout + result.stderr
            log_entry = {
                'time': datetime.utcnow().isoformat(),
                'command': command,
                'exit_status': exit_status
            }
            self.log_file.write(json.dumps(log_entry) + '\n')
            self.log_file.flush()
        except Exception as e:
            error_entry = {
                'message': str(e)
            }
            sys.stderr.write(json.dumps(error_entry) + '\n')
            sys.exit(1)

    def run_command(self, command):
        def worker():
            self.throttle_event.wait()
            self.last_command_time = time.time()
            self.process_command(command)
            self.throttle_event.set()
            self.throttle_start = time.time()

        thread = Thread(target=worker)
        self.active_threads.append(thread)
        thread.start()

    def read_commands(self):
        for line in sys.stdin:
            line = line.strip()
            if line:
                self.command_queue.append(line)

    def main_loop(self):
        while self.command_queue or self.active_threads:
            if not self.command_queue:
                self.throttle_event.wait(1)
                continue

            if len(self.active_threads) < 5:
                command = self.command_queue.pop(0)
                self.run_command(command)

            time.sleep(0.1)

    def cleanup(self):
        self.log_file.close()
        for thread in self.active_threads:
            thread.join()

if __name__ == "__main__":
    import subprocess
    runner = CommandRunner()
    try:
        runner.read_commands()
        runner.main_loop()
    except Exception as e:
        error_entry = {
            'message': str(e)
        }
        sys.stderr.write(json.dumps(error_entry) + '\n')
        sys.exit(1)
    finally:
        runner.cleanup()
        sys.exit(0)
